insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"missing_verbs_q01_finish","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_q01_start","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_q02_finish","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_q02_start","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_q03_finish","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_q03_start","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"missing_verbs_q01_finish","locale":"he","line_order":0,"content":"כל הכבוד! עכשיו הבנאים יודעים איזו פעולה לבצע.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q01_finish","locale":"he","line_order":1,"content":"השומר בשער צריך עזרה עם פקודות המלך. לכו אליו עם הרשימה.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q01_start","locale":"he","line_order":0,"content":"היי! הבנאים שלי עומדים ליד הקיר ולא יודעים מה לעשות.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q01_start","locale":"he","line_order":1,"content":"עזרו לי להחזיר את פעלי הפעולה לפקודות. קראו את ההוראות בעברית ובצעו את המשימות באנגלית.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q02_finish","locale":"he","line_order":0,"content":"מצוין! עכשיו אני מבין כל פקודה ויודע איזו פעולה לבצע.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q02_finish","locale":"he","line_order":1,"content":"התותחן מחכה ליד התותח. הוא צריך את העזרה האחרונה שלכם.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q02_start","locale":"he","line_order":0,"content":"אוי! פעלי הפעולה נעלמו מפקודות המלך, ואני לא יודע מה לעשות.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q02_start","locale":"he","line_order":1,"content":"עזרו לי לבחור ולסדר את הפעלים הנכונים. אחר כך הפקודות יהיו ברורות.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q03_finish","locale":"he","line_order":0,"content":"הצלחתם! עכשיו הפקודה ברורה, ואני יודע איזו פעולה לבצע.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q03_finish","locale":"he","line_order":1,"content":"פעלים מתארים פעולות. כל הכבוד — סיימתם את שיעורי הבית! קבלו את הפרס שלכם.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q03_start","locale":"he","line_order":0,"content":"אוי! הפועל נעלם מהפקודה שלי, ואני כמעט מנחש מה לעשות עם התותח.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_q03_start","locale":"he","line_order":1,"content":"עזרו לי לשחזר את פועל הפעולה, לבחור אותו במשפט ולומר אותו באנגלית.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
